export const extraInputComposerFamilySpecifics = Object.entries(additions).flatMap(([family, entries]) => {
  const target = familyTargets[family];
  return entries.map(([suffix, tags], index) => ({
    id: `${family}-specific-extra-${String(index + 1).padStart(2, '0')}`,
    family,
    difficulty: index < 3 ? 'normal' : 'advanced',
    input: `${target}${suffix}`,
    expectAttributes: [],
    expectUnresolved: [],
    tags,
    templateKey: `specific:${family}:extra:${index + 1}`,
    familySpecific: true,
  }));
});
